// The sequence parameter set reader the encode probe checks streams with,
// against parameter sets real encoders wrote (x264, x265 and VideoToolbox), so
// that "the stream is the size that was asked for" means what a decoder would
// see: cropping and all.
#include <vector>

#include "annexb.hpp"
#include "test_support.hpp"

namespace uml::va::test {
namespace {

struct Case {
    const char* name;
    bool hevc;
    std::vector<std::uint8_t> nal;
    unsigned profile;
    unsigned level;
    unsigned codedWidth;
    unsigned codedHeight;
    unsigned width;
    unsigned height;
};

// A start code in front of the NAL unit, as a stream carries it.
std::vector<std::uint8_t> withStartCode(const std::vector<std::uint8_t>& nal)
{
    std::vector<std::uint8_t> out {0, 0, 0, 1};
    out.insert(out.end(), nal.begin(), nal.end());
    return out;
}

void run(const Case& item)
{
    const auto stream = withStartCode(item.nal);
    const auto nals = annexb::splitNals(stream, item.hevc);
    if (nals.size() != 1) { check(false, item.name); return; }
    const annexb::StreamInfo info = item.hevc ? annexb::parseHevcSps(nals[0].payload, nals[0].size)
                                              : annexb::parseH264Sps(nals[0].payload, nals[0].size);
    const bool good = info.found && info.profile == item.profile && info.level == item.level &&
                      info.codedWidth == item.codedWidth && info.codedHeight == item.codedHeight &&
                      info.width == item.width && info.height == item.height;
    check(good, item.name);
}

}

void runAnnexbTests()
{
    const Case cases[] = {
        {"x264 baseline 176x144", false,
         {0x67, 0x42, 0xc0, 0x0b, 0xd9, 0x02, 0xc4, 0xec, 0x04, 0x40, 0x00, 0x00, 0x03, 0x00, 0x40, 0x00, 0x00, 0x0f,
          0x03, 0xc5, 0x0a, 0x92},
         66, 11, 176, 144, 176, 144},
        {"x264 main 1920x1080 cropped from 1088", false,
         {0x67, 0x4d, 0x40, 0x28, 0xec, 0xa0, 0x3c, 0x01, 0x13, 0xf2, 0xe0, 0x22, 0x00, 0x00, 0x03, 0x00, 0x02, 0x00,
          0x00, 0x03, 0x00, 0x78, 0x1e, 0x30, 0x63, 0x2c},
         77, 40, 1920, 1088, 1920, 1080},
        {"x264 high 640x360 cropped from 368", false,
         {0x67, 0x64, 0x00, 0x1e, 0xac, 0xd9, 0x40, 0xa0, 0x2f, 0xf9, 0x70, 0x11, 0x00, 0x00, 0x03, 0x00, 0x01, 0x00,
          0x00, 0x03, 0x00, 0x3c, 0x0f, 0x16, 0x2d, 0x96},
         100, 30, 640, 368, 640, 360},
        {"VideoToolbox high 1920x1080", false,
         {0x27, 0x64, 0x00, 0x28, 0xac, 0x56, 0x50, 0x1e, 0x00, 0x89, 0xf9, 0x50},
         100, 40, 1920, 1088, 1920, 1080},
        {"x265 main 176x144", true,
         {0x42, 0x01, 0x01, 0x01, 0x60, 0x00, 0x00, 0x03, 0x00, 0x90, 0x00, 0x00, 0x03, 0x00, 0x00, 0x03, 0x00, 0x3c,
          0xa0, 0x16, 0x20, 0x24, 0x59, 0x65, 0x66, 0x92, 0x4c, 0xaf, 0x01, 0x68, 0x08, 0x00, 0x00, 0x03, 0x00, 0x08,
          0x00, 0x00, 0x03, 0x00, 0xf0, 0x40},
         1, 60, 176, 144, 176, 144},
        {"x265 main 1920x1080", true,
         {0x42, 0x01, 0x01, 0x01, 0x60, 0x00, 0x00, 0x03, 0x00, 0x90, 0x00, 0x00, 0x03, 0x00, 0x00, 0x03, 0x00, 0x78,
          0xa0, 0x03, 0xc0, 0x80, 0x10, 0xe5, 0x96, 0x56, 0x69, 0x24, 0xca, 0xf0, 0x16, 0x80, 0x80, 0x00, 0x00, 0x03,
          0x00, 0x80, 0x00, 0x00, 0x0f, 0x04},
         1, 120, 1920, 1080, 1920, 1080},
        {"x265 main 640x360", true,
         {0x42, 0x01, 0x01, 0x01, 0x60, 0x00, 0x00, 0x03, 0x00, 0x90, 0x00, 0x00, 0x03, 0x00, 0x00, 0x03, 0x00, 0x3f,
          0xa0, 0x05, 0x02, 0x01, 0x69, 0x65, 0x95, 0x9a, 0x49, 0x32, 0xbc, 0x05, 0xa0, 0x20, 0x00, 0x00, 0x03, 0x00,
          0x20, 0x00, 0x00, 0x03, 0x03, 0xc1},
         1, 63, 640, 360, 640, 360},
        {"VideoToolbox main 1920x1080 cropped from 1088", true,
         {0x42, 0x01, 0x01, 0x01, 0x60, 0x00, 0x00, 0x03, 0x00, 0xb0, 0x00, 0x00, 0x03, 0x00, 0x00, 0x03, 0x00, 0x78,
          0xa0, 0x03, 0xc0, 0x80, 0x11, 0x07, 0xcb, 0x88, 0x1b, 0xb9, 0x16, 0x45, 0x2f, 0xfc, 0xb9, 0xfc, 0x4f, 0xeb,
          0x01, 0x6a, 0x04, 0x04, 0x04, 0x01},
         1, 120, 1920, 1088, 1920, 1080},
    };
    for (const auto& item : cases) run(item);

    // Several NAL units, found by their start codes, whatever their length.
    const std::vector<std::uint8_t> stream {0, 0, 0, 1, 0x67, 1, 2, 0, 0, 1, 0x68, 3, 0, 0, 0, 1, 0x65, 4, 5, 6, 0};
    const auto nals = annexb::splitNals(stream, false);
    check(nals.size() == 3 && nals[0].type == 7 && nals[0].size == 2 && nals[1].type == 8 && nals[1].size == 1 &&
              nals[2].type == 5 && nals[2].size == 3,
          "NAL units are found by their start codes, with trailing zeros dropped");
}

}
